const http = require('http');
const orders = require('./db/orders');
const users = require('./db/users');
http.createServer(async (req, res) => {
  const u = new URL(req.url, 'http://x');
  if (u.pathname === '/orders') return res.end(JSON.stringify(await orders.byStatus(u.searchParams.get('status'))));
  if (u.pathname === '/users') return res.end(JSON.stringify(await users.byEmail(u.searchParams.get('email'))));
  res.end('ok');
}).listen(3000);

const http = require('http');
const ping = require('./routes/ping');
const trace = require('./routes/trace');
http.createServer((req, res) => {
  const u = new URL(req.url, 'http://x');
  if (u.pathname === '/ping') return ping(u.searchParams.get('host'), res);
  if (u.pathname === '/trace') return trace(u.searchParams.get('host'), res);
  res.end('ok');
}).listen(3000);

