const { execFile } = require('child_process');
module.exports = function trace(host, res) {
  if (!/^[a-z0-9.-]{1,253}$/i.test(String(host))) { res.statusCode = 400; return res.end('bad host'); }
  execFile('traceroute', ['-m', '5', host], (err, out) => res.end(err ? 'fail' : out));
};
